try {
    let data = msg.payload;
    if (typeof data === 'string') { data = JSON.parse(data); }
    if (!data || typeof data !== 'object') { throw new Error('Télémétrie invalide'); }

    data.receivedAt = Date.now();
    flow.set('bottleTelemetry', data);

    const samples = flow.get('bottleSamples') || [];
    samples.push({
        timestamp: data.receivedAt,
        total: Number(data.totals?.passages || 0),
        good: Number(data.totals?.good || 0),
        reject: Number(data.totals?.reject || 0),
        defectRate: Number(data.defectRate || 0)
    });
    while (samples.length > 120) { samples.shift(); }
    flow.set('bottleSamples', samples);

    msg.statusCode = 200;
    msg.headers = {
        'Content-Type': 'application/json; charset=utf-8',
        'Access-Control-Allow-Origin': '*',
        'Cache-Control': 'no-store'
    };
    msg.payload = { ok: true, receivedAt: data.receivedAt };
    return msg;
} catch (error) {
    msg.statusCode = 400;
    msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*' };
    msg.payload = { ok: false, error: error.message };
    return msg;
}

const emptyState = {
    status: 'ARRÊTÉE', running: false, paused: false, fault: false,
    totals: { passages: 0, good: 0, reject: 0, packed: 0 },
    defectRate: 0, productsPerMinute: 0, currentProducts: 0,
    queues: { packaging: 0, quality: 0 },
    machines: { packaging: 'DISPONIBLE', quality: 'DISPONIBLE' },
    config: { speed: 90, interval: 5, packTime: 3, qualityTime: 2, defectProbability: 20 },
    history: [], lastQuality: null, receivedAt: 0
};
const latest = flow.get('bottleTelemetry') || emptyState;
const samples = (flow.get('bottleSamples') || []).slice(-60);
msg.headers = {
    'Content-Type': 'application/json; charset=utf-8',
    'Access-Control-Allow-Origin': '*',
    'Cache-Control': 'no-store'
};
msg.payload = {
    ...latest,
    online: Date.now() - Number(latest.receivedAt || 0) < 2500,
    samples
};
return msg;

try {
    let command = msg.payload;
    if (typeof command === 'string') { command = JSON.parse(command); }
    if (!command || typeof command !== 'object' || !command.action) {
        throw new Error('Commande invalide');
    }
    command.id = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
    command.createdAt = Date.now();
    flow.set('bottleCommand', command);
    msg.statusCode = 200;
    msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*', 'Cache-Control': 'no-store' };
    msg.payload = { ok: true, command };
    return msg;
} catch (error) {
    msg.statusCode = 400;
    msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*' };
    msg.payload = { ok: false, error: error.message };
    return msg;
}

msg.headers = {
    'Content-Type': 'application/json; charset=utf-8',
    'Access-Control-Allow-Origin': '*',
    'Cache-Control': 'no-store'
};
msg.payload = flow.get('bottleCommand') || { id: null, action: null };
return msg;
